                    // Update existing record
                    existingRole_B0004_DoA3_7283.Name = $"DoA3_OrganizationHierarchy - {orgUnit_B0004Id} - {user_B0004_DoA3_7283Id}";
                    existingRole_B0004_DoA3_7283.Status = EntityStatus.Active;
                    existingRole_B0004_DoA3_7283.LastModifiedDate = DateTime.UtcNow;
